package com.fixflow.mall.service;

import com.fixflow.mall.domain.MallUser;
import com.fixflow.mall.repo.UserRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
@DisplayName("UserService Tests")
public class UserServiceTest {

    @Mock
    private UserRepository userRepository;

    @InjectMocks
    private UserService userService;

    private MallUser testUser;

    @BeforeEach
    void setUp() {
        testUser = new MallUser();
        testUser.setId(1L);
    }

    @Test
    @DisplayName("正向测试：profileJson格式正确时返回正确的昵称")
    void getNickname_WithValidProfileJson_ReturnsNickname() {
        // Given
        testUser.setProfileJson("nickname:JohnDoe");
        when(userRepository.findById(1L)).thenReturn(Optional.of(testUser));

        // When
        String result = userService.getNickname(1L);

        // Then
        assertEquals("JohnDoe", result);
    }

    @Test
    @DisplayName("边界测试：profileJson为null时不抛出异常，返回null")
    void getNickname_WithNullProfileJson_ReturnsNull() {
        // Given
        testUser.setProfileJson(null);
        when(userRepository.findById(1L)).thenReturn(Optional.of(testUser));

        // When
        String result = userService.getNickname(1L);

        // Then
        assertNull(result);
    }

    @Test
    @DisplayName("边界测试：profileJson为空字符串时不抛出异常，返回null")
    void getNickname_WithEmptyProfileJson_ReturnsNull() {
        // Given
        testUser.setProfileJson("");
        when(userRepository.findById(1L)).thenReturn(Optional.of(testUser));

        // When
        String result = userService.getNickname(1L);

        // Then
        assertNull(result);
    }

    @Test
    @DisplayName("边界测试：profileJson不包含冒号时不抛出异常，返回null")
    void getNickname_WithProfileJsonWithoutColon_ReturnsNull() {
        // Given
        testUser.setProfileJson("noColon");
        when(userRepository.findById(1L)).thenReturn(Optional.of(testUser));

        // When
        String result = userService.getNickname(1L);

        // Then
        assertNull(result);
    }

    @Test
    @DisplayName("边界测试：profileJson只包含冒号时不抛出异常，返回null")
    void getNickname_WithProfileJsonOnlyColon_ReturnsNull() {
        // Given
        testUser.setProfileJson(":");
        when(userRepository.findById(1L)).thenReturn(Optional.of(testUser));

        // When
        String result = userService.getNickname(1L);

        // Then
        assertNull(result);
    }

    @Test
    @DisplayName("正向测试：profileJson包含多个冒号时返回第一部分")
    void getNickname_WithMultipleColons_ReturnsFirstPart() {
        // Given
        testUser.setProfileJson("key:value:extra");
        when(userRepository.findById(1L)).thenReturn(Optional.of(testUser));

        // When
        String result = userService.getNickname(1L);

        // Then
        assertEquals("value", result);
    }

    @Test
    @DisplayName("异常测试：用户不存在时抛出异常")
    void getNickname_WhenUserNotFound_ThrowsException() {
        // Given
        when(userRepository.findById(anyLong())).thenReturn(Optional.empty());

        // When & Then
        assertThrows(RuntimeException.class, () -> userService.getNickname(1L));
    }
}
